<script setup lang="ts">import { ref } from 'vue';import { api } from '../../api';const selected=ref<any[]>([]);const compared=ref<any>(null);async function compare(){compared.value=await api.compareSchools(selected.value.map(x=>x.school_id))}</script><template><section class="content-page"><div class="eyebrow">SCHOOLS / COMPARE</div><h1>院校对比</h1><p class="lede">最多选择五所院校并排查看关键指标。</p><div class="result-grid"><article v-for="s in [{school_id:'demo-1',name:'演示院校一',province:'河南'},{school_id:'demo-2',name:'演示院校二',province:'河南'}]" :key="s.school_id" class="feature-card" @click="selected.includes(s)?selected=selected.filter(x=>x!==s):selected.length<5&&selected.push(s)"><h2>{{s.name}}</h2><p>{{selected.includes(s)?'已选择':'点击选择'}}</p></article></div><button class="primary" :disabled="!selected.length" @click="compare">开始对比 ↗</button><div v-if="compared" class="state-box">已生成演示对比，请以来源数据为准。</div></section></template>
